        assert_eq!(defesa_do_mob(8, 30), shared::ladder::mob(&shared::ladder::Profile::relativo_ao_lobo(280, 18, 8), 30).defense);
        assert_eq!(folego_de_iniciante(11, 100, 10.0), 0.0);
